const why = {
  buttons: `<div class="why"><p>Wskazówka: dostępna nazwa przycisku powinna jasno wskazywać, co przycisk robi po kliknięciu. Jeśli to się zmienia, aktualny stan powinien być wyraźny:</p><ul><li>Przyciski zmieniające etykietę:<br>„Odtwórz/Wstrzymaj”, „Pokaż szczegóły/Ukryj szczegóły”</li><li>Przyciski zmieniające <a href="https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/button_role#associated_aria_roles_states_and_properties">stan</a>:<br>„Odtwórz/Odtwórz, wciśnięty”, „Szczegóły, zwinięte/Szczegóły, rozwinięte”</li></ul></div>`,
  fix: `<strong class="badge">Jak naprawić</strong> `,
  headings: `<div class="why"><p>Wskazówka: nagłówki i podnagłówki porządkują treść w zagnieżdżoną strukturę. Użytkownicy czytników ekranu polegają na niej, aby rozumieć i przeglądać strony:</p><ul><li>Nagłówek poziomu 1: tytuły stron<ul><li>Nagłówek poziomu 2: główne tematy<ul><li>Nagłówek poziomu 3: podtematy</li></ul></li></ul></li></ul></div>`,
  imageLinks: `<div class="why"><p>Wskazówka: celem tekstu alternatywnego jest opisanie znaczenia obrazu, a nie tylko jego zawartości. W przypadku obrazu będącego linkiem znaczeniem jest cel linku:</p><ul><li>„<em>Lupa</em>” opisuje obraz, a nie link.</li><li>„<em>Lupa, wyszukiwanie</em>” w mylący sposób opisuje jedno i drugie.</li><li>„<em>Szukaj</em>” poprawnie opisuje cel linku.</li></ul></div>`,
  images: `<div class="why"><p>Wskazówka: pisząc tekst alternatywny, opisz to, co obraz <em>znaczy</em> w danym kontekście, nie tylko to, co przedstawia. Zdjęcie dziecka kopiącego piłkę może oznaczać:</p><ul><li>Grali mimo ulewy.</li><li>Nowe stroje mają efektowne smocze logo.</li><li>Zdobyła zwycięskiego gola z lewej strony boiska!</li></ul></div>`,
  links: `<div class="why"><p>Wskazówka: użytkownicy szybko przeglądają stronę, zwracając uwagę na linki, i używają wyszukiwania na stronie, aby znaleźć je po nazwie. Skuteczne linki są znaczące, unikalne i zwięzłe:</p><ul><li>Idealne: „Dowiedz się więcej o <a href="https://webaim.org/techniques/hypertext/link_text">znaczących linkach</a>”</li><li>Nieunikalne: „Kliknij <a href="https://webaim.org/techniques/hypertext/link_text">tutaj</a>, aby dowiedzieć się więcej o znaczących linkach”.</li><li>Niezwięzłe: „<a href="https://webaim.org/techniques/hypertext/link_text">Kliknij tutaj, aby dowiedzieć się więcej o znaczących linkach</a>”</li></ul></div>`
};
const tips = {
  ARIA_INPUT_FIELD_NAME: `<p><strong>Element:</strong> <code>%(EL)</code></p><p>${why.fix}Podaj dowolną prawidłową etykietę; w przypadku niestandardowych elementów wejściowych oznacza to zazwyczaj tekst wewnętrzny lub atrybut title, aria-label albo aria-labelledby.</p>`,
  ALT_FILE_EXT: `<p><span hidden>%(alt)</span><strong>Tekst alternatywny:</strong> <i>%(ALT_TEXT)</i></p><p>Czytniki ekranu spróbują wymówić ten adres URL, często litera po literze. Prawdopodobnie nie odda to znaczenia obrazu.</p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p>${why.images}`,
  ALT_MAYBE_BAD: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p>${why.images}`,
  ALT_MAYBE_BAD_WARNING: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p>${why.images}`,
  ALT_PLACEHOLDER: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p>${why.images}`,
  ALT_UNPRONOUNCEABLE: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>Ten tekst alternatywny zawiera tylko niewymawialne symbole lub spacje. Czytniki ekranu ogłoszą obecność obrazu, po czym zrobią niezręczną pauzę lub odczytają niezrozumiały ciąg.</p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p>${why.images}`,
  BTN_EMPTY: `<p>${why.fix}Użyj dowolnej prawidłowej metody, aby przekazać czytnikom ekranu, do czego służy ten przycisk, np. tekstu, tekstu alternatywnego ikony lub atrybutu title.</p>`,
  BTN_EMPTY_LABELLEDBY: `<p>Ten przycisk ma wartość <code>aria-labelledby</code>, która jest pusta lub nie pasuje do wartości <code>ID</code> innego elementu na stronie.</p><p>${why.fix}Ponownie powiąż ID z elementem na stronie albo usuń ten atrybut i opisz przycisk w inny sposób.</p>`,
  BTN_ROLE_IN_NAME: `<p><strong>Etykieta dla czytników ekranu:</strong> <i>%(TEXT)</i></p><p>Czytniki ekranu używają słowa „przycisk”, aby zapowiedzieć, że opisują przycisk, więc to słowo się powtarza.</p><p>${why.fix}Etykieta przycisku powinna odpowiadać jego działaniu. Jeśli widoczną etykietą jest ikona, a nie tekst, opisz przycisk zgodnie ze znaczeniem ikony, np. „Odtwórz”, „Szukaj” lub „Menu”.</p>`,
  BTN_TIP: `${why.buttons}`,
  BTN_UNPRONOUNCEABLE: `<p><strong>Tekst przycisku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Dodaj tekst, tytuł lub atrybut aria-label opisujący, do czego służy.</p><div class="why"><p>Wskazówka: czytniki ekranu nie mogą opisać przycisków zawierających tylko spacje lub symbole. Albo milkną („Przycisk, [...niezręczna pauza w miejscu etykiety przycisku...]”), albo odczytują nazwę symbolu.</p></div>`,
  CONTRAST_WARNING: "Obraz tła lub gradient sprawia, że to narzędzie nie ma pewności, jaki kolor znajduje się za tym tekstem. Użyj poniższego selektora kolorów, aby sprawdzić kontrast ręcznie.",
  DUPLICATE_ID: `<p>Identyfikatory (ID) na tej stronie są używane w etykietach lub jako cele linków, więc muszą być unikalne.</p><p>${why.fix}Zmień ten identyfikator: <code>#%(ID)</code></p><div class="why"><p>W większości systemów zarządzania treścią pochodzi on z pola o nazwie „name” lub „id” we właściwościach elementu. W HTML jest to atrybut: <code>&lt;a id="MOJE-ID"&gt;</code></p></div>`,
  DUPLICATE_TITLE: `<p>${why.fix}Usuń tekst lub atrybut <code>title</code> z tego linku.</p><div class="why"><p>Wskazówka: podpowiedzi z atrybutu <code>title</code> pojawiają się tylko po najechaniu myszą. Nie są widoczne na telefonach ani przy nawigacji klawiaturą, więc wielu użytkowników nigdy ich nie zobaczy. Nigdy nie powinny zawierać unikalnych ani ważnych informacji.</p></div>`,
  EMBED_AUDIO: `<p>To narzędzie nie jest w stanie stwierdzić, czy odtwarzacz audio ma transkrypcję, ani czy transkrypcja jest dokładna.</p><p>${why.fix}Sprawdź, czy dostępna jest <a href="https://www.w3.org/WAI/media/av/transcribing/">transkrypcja lub tekstowa alternatywa</a>, i upewnij się, że mówcy oraz znaczące efekty dźwiękowe są prawidłowo oznaczeni.</p>`,
  EMBED_DATA_VIZ: `<p>Osadzone widżety z wizualizacjami są często trudne lub niemożliwe do obsługi za pomocą technologii wspomagających, mogą być trudne do zrozumienia dla osób słabowidzących lub z zaburzeniami widzenia barw i mogą wymagać intensywnego przewijania w poziomie na telefonach.</p><p>${why.fix}Jeśli ten osadzony element nie ma wysokiego kontrastu i nie daje się obsłużyć klawiaturą <strong><em>oraz</em></strong> opisać czytnikiem ekranu, dodaj równoważny, alternatywny format, np. opis tekstowy, tabelę danych lub arkusz kalkulacyjny do pobrania.</p>`,
  EMBED_GENERAL: 'Automatyczne narzędzia nie mogą sprawdzić treści wewnątrz osadzonych elementów. Upewnij się, że ktoś sprawdził, czy wszystkie obrazy w tym osadzonym elemencie mają tekst alternatywny, filmy mają napisy, tekst ma wystarczający kontrast, a linki i przyciski są <a href="https://webaim.org/techniques/keyboard/">dostępne z klawiatury</a>.',
  EMBED_MISSING_TITLE: `<p>Osadzone elementy potrzebują dostępnej nazwy, która opisuje ich zawartość dla czytników ekranu.</p><p>${why.fix}Dodaj unikalny atrybut <code>title</code> lub <code>aria-label</code>.</p>`,
  EMBED_UNFOCUSABLE: `<p>Ten atrybut nakazuje klawiaturom i urządzeniom wspomagającym pominięcie elementu. Usuń ten atrybut, chyba że iframe nie zawiera żadnych linków, przycisków, pól formularza ani przewijalnej treści.</p>`,
  EMBED_VIDEO: `<p>To narzędzie nie jest w stanie „zobaczyć”, czy filmy mają napisy, ani stwierdzić, czy ktoś je sprawdził — konieczna jest ręczna weryfikacja.</p><p>${why.fix}Sprawdź, czy dostępne są <a href="https://www.w3.org/WAI/media/av/captions/">dokładne napisy dla niesłyszących („CC”) lub napisy</a>, i upewnij się, że mówcy oraz znaczące efekty dźwiękowe są prawidłowo oznaczeni.</p>`,
  HEADING_EMPTY: `<p>Puste nagłówki tworzą mylące luki w strukturze strony.</p><p>${why.fix}Dodaj tekst do tego nagłówka albo usuń tę pustą linię.</p>${why.headings}`,
  HEADING_UNPRONOUNCEABLE: `<p>Puste nagłówki tworzą mylące luki w strukturze strony.</p><p>${why.fix}Dodaj do tego nagłówka tekst zrozumiały dla człowieka albo zmień go w akapit.</p>${why.headings}`,
  HEADING_EMPTY_WITH_IMAGE: `<p>Puste nagłówki tworzą mylące luki w strukturze strony.</p><p>${why.fix}Jeśli to nie jest nagłówek, zmień jego format z <code>Nagłówek %(level)</code> na <code>Akapit</code>. W przeciwnym razie opisz znaczenie obrazu w jego tekście alternatywnym.</p>${why.headings}`,
  HEADING_FIRST: `${why.fix}Upewnij się, że tytuł strony jest oznaczony jako Nagłówek 1 lub Nagłówek 2. ${why.headings}`,
  HEADING_LONG: `<p>${why.fix}Jeśli ten nagłówek nie jest stałym odniesieniem, np. tytułem opublikowanego artykułu, skróć go, aby ułatwić szybkie przeglądanie:<span hidden>%(drop)%(drop)</span></p><p><i>%(TEXT)</i></p>${why.headings}`,
  HEADING_MISSING_ONE: `<p>${why.fix}Oznacz tytuł strony jako nagłówek poziomu 1, aby wyznaczyć początek struktury dokumentu.</p>${why.headings}`,
  HEADING_SKIPPED_LEVEL: `<p>Ten nagłówek przeskakuje z <code>poziomu %(prevLevel)</code> na <code>poziom %(level)</code>. W czytniku ekranu brzmi to tak, jakby brakowało treści.</p><p>${why.fix}Dostosuj poziomy, aby tworzyły dokładną strukturę bez luk.</p>${why.headings}`,
  HIDDEN_FOCUSABLE: `<p>Ten interaktywny element ma atrybut <code>aria-hidden=&quot;true&quot;</code>, ale nadal może otrzymać fokus klawiatury.</p><p>${why.fix}Jeśli <strong>celowo</strong> ukrywasz ten element przed czytnikami ekranu, musisz też dodać <code>tabindex=&quot;-1&quot;</code>. W przeciwnym razie usuń atrybut <code>aria-hidden=&quot;true&quot;</code>.</p><p><strong>Element:</strong> <code>%(ELEMENT)</code></p>`,
  IMAGE_ALT_TOO_LONG: `<p>Ten tekst alternatywny ma długość %(altLength) znaków: <i class="ed11y-small">%(ALT_TEXT)</i></p><p>${why.fix}Podsumuj go lub część opisu przenieś do podpisu pod obrazem.</p><div class="why"><p>Wskazówka: złożone obrazy, które przekazują więcej informacji niż mieści się w jednym zdaniu, zazwyczaj wymagają <strong>widocznego</strong> podpisu lub alternatywy opisującej najważniejsze szczegóły. Możesz skierować użytkowników czytników ekranu do takiego podpisu:</p><ul><li>„Plakat zapraszający na piątkową zabawę; szczegóły w podpisie.”</li><li>„Wykres pokazujący spadek liczby zgłoszeń o 10% w tym roku; szczegóły w tabeli.”</li></ul></div>`,
  IMAGE_DECORATIVE: `<p>Ten obraz został ukryty przed czytnikami ekranu za pomocą pustego tekstu alternatywnego. W ten sposób należy ukrywać tylko obrazy bez znaczenia, takie jak zbędne ikony czy tekstury tła.</p><p>${why.fix}Jeśli ten obraz wnosi coś do strony, dodaj tekst alternatywny.</p>${why.images}`,
  IMAGE_DECORATIVE_CAROUSEL: "Obraz jest oznaczony jako <strong>dekoracyjny</strong>, ale wszystkie obrazy w karuzeli lub galerii powinny mieć opisowy tekst alternatywny, aby zapewnić wszystkim równoważne doświadczenie.",
  IMAGE_FIGURE_DECORATIVE: `<p>Ten obraz zostanie pominięty przez technologie wspomagające. Czy jego podpis będzie zrozumiały bez obrazu?</p><p>${why.fix}Jeśli podpis nie opisuje wizualnego znaczenia obrazu, dodaj tekst alternatywny opisujący to, czego nie opisuje podpis.</p><div class="why"><p>Wskazówka: obrazy, teksty alternatywne i podpisy współdziałają ze sobą:</p><ul><li>Widoczne podpisy zapewniają kontekst i interpretację obrazu.</li><li>Niewidoczne teksty alternatywne opisują obraz osobom, które go nie widzą, aby wiedziały, co opisuje podpis.</li></ul></div>`,
  IMAGE_FIGURE_DUPLICATE_ALT: `<p><strong>Powtórzony tekst: </strong><i>%(ALT_TEXT)</i></p><p>${why.fix}Opisz w tekście alternatywnym brakujące znaczenie wizualne.</p><div class="why"><p>Wskazówka: obrazy, teksty alternatywne i podpisy współdziałają ze sobą:</p><ul><li>Widoczne podpisy zapewniają kontekst i interpretację obrazu.</li><li>Niewidoczne teksty alternatywne opisują obraz osobom, które go nie widzą, aby wiedziały, o czym mówi podpis.</li></ul></div>`,
  LABELS_ARIA_LABEL_INPUT: `<p><strong>Niewidoczna etykieta pola:</strong> <i>%(TEXT)</i></p><p>Sprawdź, czy istnieje widoczna etykieta pola, czy pozostaje widoczna, gdy w polu jest tekst, i czy jest zgodna z niewidoczną nazwą pola.</p><div class="why"><p>Jeśli pole jest opisane tylko atrybutem title lub tekstem zastępczym, etykieta znika z widoku, gdy tylko ktoś zacznie pisać. Utrudnia to sprawdzenie wprowadzonych danych, gdy pól jest kilka. Łatwo też zapomnieć o zaktualizowaniu niewidocznej etykiety pola.</p></div>`,
  LABELS_INPUT_RESET: `<p>Przyciski resetowania łatwo aktywować przez pomyłkę, co powoduje utratę danych bez możliwości anulowania lub cofnięcia.</p><p>${why.fix}Jeśli ten przycisk nie resetuje pojedynczego pola, rozważ jego usunięcie lub zapewnienie możliwości anulowania przed wykonaniem akcji.</p>`,
  LABELS_MISSING_IMAGE_INPUT: "Przycisk graficzny nie ma tekstu alternatywnego. Dodaj tekst alternatywny, aby nadać mu dostępną nazwę. Na przykład: <em>Szukaj</em> lub <em>Wyślij</em>.",
  LABELS_MISSING_LABEL: `<p>${why.fix}Dodaj atrybut <code>id</code> do tego pola oraz odpowiadający mu atrybut <code>for</code> do etykiety.</p>`,
  LABELS_NO_FOR_ATTRIBUTE: `To pole nie ma powiązanej etykiety. Dodaj do etykiety atrybut <code>for</code>, dopasowany do <code>id</code> tego pola. <hr> <strong>ID:</strong> <code>#%(ID)</code>`,
  LABELS_PLACEHOLDER: `<p>Tekst zastępczy może zostać pomylony z wcześniej wprowadzoną treścią, jeśli ma dobry kontrast, lub być nieczytelny, jeśli go nie ma. Następnie znika po wpisaniu danych, co może usunąć informacje potrzebne użytkownikom do sprawdzenia błędów.</p><p>${why.fix}Upewnij się, że kluczowe informacje, takie jak etykieta pola, tekst pomocy i instrukcje dotyczące formatu, pozostają widoczne, gdy w polu jest treść, i rozważ całkowitą rezygnację z tekstu zastępczego.</p>`,
  LABEL_IN_NAME: `<p><strong>Widoczny tekst:</strong> <i>%(VISIBLE)</i></p><p><strong>Etykieta dla czytników ekranu:</strong> <i>%(LABEL)</i></p><p>Widoczny tekst tego elementu różni się od jego dostępnej nazwy. Może to wprowadzać w błąd użytkowników czytników ekranu oraz zakłócać sterowanie głosowe.</p><p>${why.fix}Upewnij się, że widoczna etykieta zaczyna się od tekstu niewidocznej etykiety i nie zawiera żadnych istotnych informacji, których brakuje w niewidocznej etykiecie.</p>`,
  LINK_ALT_FILE_EXT: `<p>Ten tekst alternatywny prawdopodobnie jest nazwą pliku, a nie znaczącą nazwą linku:<br><span hidden>%(ALT)</span><i>%(alt)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p><div class="why"> <p>Cel tekstu alternatywnego to opisanie, co obraz znaczy. W przypadku obrazu będącego linkiem oznacza to cel linku:</p><ul><li>„Strona z tekstem” opisuje obraz, nie link.</li><li>„IMG_1234.jpg” to tylko nazwa pliku.</li><li>„Formularz zgłoszeniowy wydarzenia (.doc)” opisuje cel linku.</li></ul></div>`,
  LINK_ALT_MAYBE_BAD: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_ALT_MAYBE_BAD_WARNING: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_ALT_UNPRONOUNCEABLE: `<p>Tekst alternatywny tego obrazu-linku zawiera tylko niewymawialne symbole lub spacje: <i>%(ALT_TEXT)</i></p><p>Czytniki ekranu ogłoszą, że jest tu link, ale nie będą w stanie go opisać.</p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_CLICK_HERE: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Usuń zbędne słowa, które odwracają uwagę od celu linku.</p>${why.links}`,
  LINK_DOI: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Podlinkuj tytuł artykułu, a numer DOI podaj jako zwykły tekst, zamiast linkować numer DOI i zostawiać tytuł artykułu jako zwykły tekst.</p><div class="why"><p><a href="https://apastyle.apa.org/style-grammar-guidelines/paper-format/accessibility/urls#:~:text=descriptive%20links">Poradnik stylu APA</a> zaleca stosowanie opisowych linków na stronach internetowych, ponieważ użytkownicy przeglądają strony, kierując się linkami, i wyszukują linki po nazwie za pomocą wyszukiwania na stronie. Użytkownicy znacznie częściej zauważą interesujące ich artykuły, gdy podlinkowany jest tytuł.</p><p>Pozwala to również czytnikom ekranu opisać każdy link w zrozumiały sposób, zamiast odczytywać bezsensowny ciąg cyfr.</p></div>`,
  LINK_EMPTY: `<p>${why.fix}Dodaj tekst opisujący cel linku albo usuń go, jeśli to tylko literówka lub podlinkowana spacja.</p><div class="why"><p>Wskazówka: czytniki ekranu nie mogą opisać linków zawierających tylko spacje lub symbole. Albo milkną („Link, [...niezręczna pauza w miejscu tytułu linku...]”), albo odczytują adres URL: „Link, H-T-T-P-S ukośnik ukośnik example kropka com”.</p><p>Pamiętaj, że w niektórych edytorach treści podlinkowane spacje trudno usunąć; czasami trzeba usunąć „przerwę” razem z sąsiednimi słowami, a następnie ponownie wpisać słowa po obu stronach podlinkowanej spacji.</p></div>`,
  LINK_EMPTY_LABELLEDBY: `<p>Ten link ma atrybut <code>aria-labelledby</code>, który nie pasuje do <code>ID</code> żadnego elementu na stronie.</p><p>${why.fix}Podaj prawidłowe <code>ID</code> albo usuń ten atrybut i opisz link w inny sposób.</p>`,
  LINK_EMPTY_NO_LABEL: `<p>${why.fix}Dodaj tekst opisujący cel linku albo usuń go, jeśli to tylko literówka, np. podlinkowana spacja.</p><div class="why"><p>Wskazówka: czytniki ekranu nie mogą opisać pustych linków. Albo milkną („Link, [...niezręczna pauza w miejscu tytułu linku...]”), albo odczytują adres URL: „Link, H-T-T-P-S ukośnik ukośnik example kropka com”.</p><p>Pamiętaj, że w niektórych edytorach treści podlinkowane spacje trudno usunąć; czasami trzeba usunąć „przerwę” razem z sąsiednimi słowami, a następnie ponownie wpisać słowa po obu stronach podlinkowanej spacji.</p></div>`,
  LINK_UNPRONOUNCEABLE: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Dodaj tekst lub tytuł opisujący cel linku albo usuń go, jeśli to tylko literówka lub podlinkowana spacja.</p><div class="why"><p>Wskazówka: czytniki ekranu nie mogą opisać linków zawierających tylko spacje lub symbole. Albo milkną („Link, [...niezręczna pauza w miejscu tytułu linku...]”), albo odczytują nazwę symbolu.</p></div>`,
  LINK_FILE_EXT: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>Ten link bez ostrzeżenia prowadzi do pliku PDF lub pliku do pobrania (np. MP3, ZIP, dokument Word).</p><p>${why.fix}Użyj tekstu lub ikony, aby <a href="https://itmaybejj.github.io/linkpurpose/">wskazać typ pliku</a> w tekście linku.</p><p class="why">W przypadku dużych plików rozważ podanie rozmiaru pliku. Na przykład: „Raport dla zarządu (PDF, 3 MB)”</p>`,
  LINK_IDENTICAL_NAME: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Zmień teksty linków prowadzących w różne miejsca na unikalne tytuły ich stron docelowych.</p>${why.links}`,
  LINK_IMAGE_ALT: `<p><strong>Tekst alternatywny:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_IMAGE_ALT_AND_TEXT: `<p><strong>Tekst alternatywny:</strong> <i>%(ALT_TEXT)</i></p><p><strong>Tekst linku zawierający tekst alternatywny:</strong> <i>%(TEXT)</i></p><p>${why.fix}Zmodyfikuj lub usuń tekst alternatywny, jeśli dodaje nieistotne lub powtórzone informacje.</p>${why.imageLinks}`,
  LINK_IMAGE_LONG_ALT: `<p>Ten tekst alternatywny ma długość %(altLength) znaków: <i class="ed11y-small">%(ALT_TEXT)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p><div class="why"><p>Użytkownicy czytników ekranu często słuchają listy linków na stronie bez kontekstu. Ponieważ tekst alternatywny obrazu-linku staje się na tej liście tytułem linku, powinien <a href="https://webaim.org/techniques/hypertext/link_text#alt_link">opisywać cel linku</a>, a nie zawartość obrazu.</p></div>`,
  LINK_IMAGE_NO_ALT_TEXT: `<p>Gdy link obejmuje obraz, tekst alternatywny obrazu <a href="https://webaim.org/techniques/hypertext/link_text#alt_link">stanowi tytuł linku dla czytników ekranu</a>.</p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_IMAGE_TEXT: "Obraz jest oznaczony jako dekoracyjny, choć link używa otaczającego tekstu jako etykiety opisowej.",
  LINK_MAYBE_BUTTON: `<p><strong>Link:</strong> <i>%(TEXT)</i></p><p>Ten link ma nieprawidłowy cel i ma nazwę sugerującą, że może działać jako przycisk lub przełącznik, a nie jako link.</p><p>${why.fix}Użyj <a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/">&lt;button&gt;</a> zamiast linku albo popraw jego cel.</p><div class="why"><p>Wskazówka: technologie wspomagające traktują przyciski i linki odmiennie. Użycie właściwego elementu HTML zapewnia, że użytkownicy wiedzą, jakich skrótów klawiszowych użyć i jaka akcja zostanie wywołana.</p></div>`,
  LINK_NEW_TAB: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Ustaw ten link tak, aby otwierał się w tej samej karcie, albo najpierw <a href="https://itmaybejj.github.io/linkpurpose/">ostrzeż użytkowników</a>.</p><div class="why"><p>Czytelnicy zawsze mogą <em>sami zdecydować</em> o otwarciu linku w nowej karcie. Gdy link wymusza otwarcie nowej karty, często jest to mylące lub irytujące, zwłaszcza dla użytkowników technologii wspomagających, którzy zastanawiają się, dlaczego przycisk „Wstecz” w przeglądarce przestał działać.</p><p>Uwaga: wyjątkiem są formularze. Gdy użytkownik wypełnia formularz, otwarcie linku w tym samym oknie mogłoby spowodować utratę wprowadzonych danych, dlatego linki w formularzach zwykle otwierają się w nowych kartach.</p></div>`,
  LINK_PLACEHOLDER_ALT: `<p><strong>Tekst alternatywny:</strong> <i>%(alt)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_STOPWORD: `<p>Tekst linku: <i>%(ERROR)</i></p><p>${why.fix}Użyj tekstu linku, który opisuje jego cel.</p>${why.links}`,
  LINK_STOPWORD_ARIA: `<p>Przy użyciu ARIA podano inną nazwę:</p><p><strong>Widoczny tekst:</strong> <i>%(VISIBLE)</i></p><p><strong>Ukryty tekst:</strong> <i>%(HIDDEN)</i></p><p>${why.fix}Pisz znaczące linki dla wszystkich, nie tylko dla użytkowników czytników ekranu, i upewnij się, że <a href="https://www.w3.org/WAI/WCAG22/Understanding/label-in-name.html">widoczna etykieta każdego elementu pasuje do jego nazwy</a>, aby użytkownicy sterowania głosowego mogli powiedzieć przeglądarce, który link kliknąć.</p>${why.links}`,
  LINK_SUS_ALT: `<p>Jeżeli „<i>%(alt)</i>” nie opisuje celu linku, ten tekst alternatywny prawdopodobnie opisuje obraz.</p><p><strong>Tekst alternatywny:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Jako tekstu alternatywnego obrazów-linków używaj tytułu celu linku.</p>${why.imageLinks}`,
  LINK_SYMBOLS: `<p>Znaleziono symbol: <i>%(ERROR)</i></p><p>${why.fix}Nie używaj symboli jako wezwania do działania w treści linku, chyba że są ukryte przed technologiami wspomagającymi. Czytniki ekranu mogą odczytywać symbole na głos, co może być mylące.</p>`,
  LINK_URL: `<p><strong>Tekst linku:</strong> <i>%(TEXT)</i></p><p>${why.fix}Zmień tekst tego linku na tytuł jego strony docelowej lub opis jego funkcji.</p><div class="why"><p>Wskazówka: czytelnicy szybko przeglądają linki po nazwach. Dotyczy to zwłaszcza użytkowników czytników ekranu, którzy nawigują i wyszukują za pomocą listy linków na stronie.</p><p>Podlinkowanych adresów URL nie da się szybko przejrzeć ani znaleźć za pomocą wyszukiwania na stronie, więc ludzie rzadziej je znajdują i rzadziej w nie klikają.</p></div>`,
  META_LANG: `<p>${why.fix}Dodaj <a href="https://www.w3.org/International/questions/qa-html-language-declarations">atrybut języka do znacznika HTML strony</a>.</p><div class="why"><p>Wskazówka: czytniki ekranu wymawiają słowa na podstawie znaczników języka. Odczytywanie tekstu z niewłaściwym pakietem językowym daje niezrozumiałą mowę. Jeśli język nie jest oznaczony, czytnik ekranu użyje domyślnego języka przeglądarki albo spróbuje go odgadnąć, z nieprzewidywalnym skutkiem.</p></div>`,
  META_LANG_VALID: `<p><strong>Element:</strong> <code>&lt;%(ELEMENT) lang="%(CODE)"&gt;</code></p><p>${why.fix}Zastąp atrybut lang prawidłowym kodem języka.</p><div class="why"><p>Wskazówka: strony i elementy mają <a href="https://www.w3.org/International/questions/qa-html-language-declarations">atrybuty języka</a>, aby czytniki ekranu i narzędzia tłumaczące poprawnie odczytywały tekst.</p></div>`,
  META_MAX: `<p>Ten metatag ogranicza możliwość powiększania tekstu przez użytkowników.</p><p>${why.fix}Zmień lub usuń to ograniczenie, aby umożliwić pełne powiększanie.</p>`,
  META_REFRESH: `<p>Strony nie powinny odświeżać się automatycznie za pomocą metatagu. Przerywa to pracę użytkownika bez ostrzeżenia i bez możliwości zapobieżenia odświeżeniu, sprawia, że gubi on miejsce, w którym czytał, i może skasować postęp w wypełnianiu formularza.</p><p>${why.fix}Aby odświeżyć treść na tej samej stronie, użyj AJAX do odświeżenia sekcji w miejscu, bez przeładowania strony, lub użyj JavaScriptu do wywołania przeładowania, tak aby użytkownik mógł zostać najpierw ostrzeżony i miał możliwość jego opóźnienia.</p>`,
  META_SCALABLE: `<p>Ten metatag uniemożliwia użytkownikom powiększanie tekstu.</p><p>${why.fix}Zmień lub usuń to ustawienie, aby umożliwić powiększanie.</p>`,
  META_TITLE: `<p>${why.fix}Dodaj znacznik <code>&lt;title&gt;</code> do elementu <code>head</code> strony.</p><div class="why"><p>Wskazówka: wiele elementów przeglądania stron zależy od <a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/title">krótkiego i unikalnego znacznika tytułu</a>:</p><ul><li>Wyszukiwarki używają go jako tytułu wyników.</li><li>Przeglądarki używają go jako tytułu kart.</li><li>Czytniki ekranu odczytują go przy przełączaniu kart.</li></ul><p>Bez tytułu strony użytkownicy widzą lub słyszą zamiast niego surowy adres URL.</p></div>`,
  MISSING_ALT: `<p>Gdy czytniki ekranu napotykają obraz w ogóle pozbawiony atrybutu alt, próbują zamiast tego wymówić adres URL pliku obrazu, często litera po literze.</p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p>${why.images}`,
  MISSING_ALT_LINK: `<p>Gdy czytniki ekranu napotykają obraz w ogóle pozbawiony atrybutu alt, próbują zamiast tego wymówić adres URL pliku obrazu, często litera po literze. Jest to szczególnie problematyczne w przypadku obrazów-linków.</p><p>${why.fix}Dodaj tekst alternatywny zgodny z celem linku.</p>${why.imageLinks}`,
  MISSING_ALT_LINK_HAS_TEXT: `<p>Ten obraz jest częścią linku z tekstem. Jeśli widoczny tekst wystarczająco opisuje link, dodaj pusty atrybut alt (alt=""), aby czytniki ekranu zignorowały ten obraz. W przeciwnym razie dodaj tekst alternatywny, który pomoże opisać cel lub przeznaczenie linku.</p>${why.imageLinks}`,
  QA_BAD_LINK: `<p>Ten link prawdopodobnie prowadzi do środowiska deweloperskiego:<br>{L} <code>%(LINK)</code></p><p>${why.fix}Zmień go tak, aby wskazywał ścieżkę względną (/folder) lub publiczny adres URL.</p>`,
  QA_BLOCKQUOTE: `<p><strong>Podejrzanie krótki cytat:</strong> <i>%(TEXT)</i></p><p>${why.fix}Jeśli to nagłówek, a nie cytat, oznacz go jako nagłówek, aby pojawił się w strukturze strony.</p>${why.headings}`,
  QA_DOCUMENT: `<p><strong>Link:</strong> <i>%(TEXT)</i></p><p>Linkowane dokumenty są traktowane jako treść internetowa i również muszą być dostępne. Sprawdź, czy w tym dokumencie oznaczono nagłówki, nagłówki tabel i teksty alternatywne obrazów.</p><div class="why"><ul><li><a href="https://support.google.com/docs/answer/6199477?hl=pl">Jak zwiększyć dostępność dokumentów i prezentacji Google Workspace</a></li><li><a href="https://support.microsoft.com/pl-pl/office/create-accessible-office-documents-868ecfcd-4f00-4224-b881-a65537a7c155">Jak zwiększyć dostępność dokumentów pakietu Office</a></li></ul></div>`,
  QA_FAKE_HEADING: `<p><strong>Pogrubiony tekst:</strong> <i>%(TEXT)</i></p><p>${why.fix}Jeśli ten tekst jest pogrubiony, aby zaznaczyć zmianę tematu, oznacz go jako nagłówek, by użytkownicy czytników ekranu mogli go wykorzystać do nawigacji po stronie.</p><div class="why"><p>Wskazówka: style pogrubione i kursywne zapewniają wyróżnienie wizualne, ale nie dodają automatycznie tekstu do spisu treści dokumentu używanego przez technologie wspomagające.</p></div>`,
  QA_FAKE_LIST: `<p>${why.fix}Jeśli ten fragment <i>%(TEXT)</i> jest częścią listy, zastąp go formatowaniem listy.</p><div class="why"><p>Wskazówka: formatowanie listy ma charakter strukturalny, zarówno wizualnie, jak i w nawigacji:</p> <ol><li>Listy wyrównują wcięcia, co ułatwia czytanie.</li> <li>Listy są czytelne dla maszyn. Czytniki ekranu pomagają użytkownikom się orientować, regularnie podając ich pozycję na liście („element 3 z 7”).</li></ol> <p>&nbsp;&nbsp;&nbsp;3. Natomiast zdanie z numerem na początku, takie jak to, nie ma wcięcia w drugim wierszu po zawinięciu i nie jest wliczane do liczby elementów podawanej użytkownikom czytników ekranu.</p></div> `,
  QA_IN_PAGE_LINK: `<p><strong>URL:</strong> <i>#%(ID)</i></p><p><strong>Link:</strong> <code>%(TEXT)</code></p><p>Cel linku nie pasuje do żadnego elementu na tej stronie.</p><div class="why"><p>Uwaga dla programistów: jeśli nie jest to zwykły link, a cel linku jest symbolem zastępczym dla zdarzenia JavaScript, przed dodaniem go do listy ignorowanych elementów narzędzia sprawdź, czy działa po aktywowaniu za pomocą klawiatury.</p></div>`,
  QA_JUSTIFY: `<p>Justowanie wstawia dodatkowe odstępy, aby wyrównać akapity jednocześnie do lewego i prawego marginesu. Nieregularne odstępy w kolejnych wierszach utrudniają czytanie wielu osobom.</p><p>${why.fix}Wyrównaj tekst do lewej.</p>`,
  QA_NESTED_COMPONENTS: "Unikaj zagnieżdżania interaktywnych komponentów układu, np. umieszczania akordeonów w innych akordeonach lub kart w akordeonach i odwrotnie. Może to utrudniać nawigację, zwiększać obciążenie poznawcze i sprawiać, że użytkownicy przeoczą treść.",
  QA_PDF: `<p><strong>Link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Wykonaj jedną z poniższych czynności:</p><ul><li>Zamiast tego podlinkuj stronę internetową,</li><li><em>Dodatkowo</em> podlinkuj stronę internetową lub edytowalny dokument, aby ten PDF był tylko wersją „do druku”, lub</li><li>Co najmniej upewnij się, że ten PDF jest czytelny dla czytników ekranu, <a href='https://webaim.org/techniques/acrobat/' target='_blank'>ręcznie sprawdzając, czy został otagowany</a> (nagłówki, kolejność czytania kolumn, nagłówki tabel i tekst alternatywny).</li>	</ul>	<div class="why"><p>Wskazówka: użytkownicy urządzeń mobilnych i technologii wspomagających niemal zawsze wolą strony internetowe od plików PDF. Pliki PDF nie dopasowują układu do ekranów urządzeń mobilnych i często brakuje w nich znaczników niezbędnych do nawigacji po tekście za pomocą czytników ekranu.</p></div>`,
  QA_SMALL_TEXT: `<p><strong>Tekst:</strong> <i>%(TEXT)</i></p><p>${why.fix}Nie schodź poniżej 80% domyślnego rozmiaru czcionki. Mały tekst jest trudny do czytania, zwłaszcza dla osób słabowidzących.</p>`,
  QA_STRONG_ITALICS: `<p><strong>Tekst:</strong> <i>%(TEXT)</i></p><p>${why.fix}Zarezerwuj pogrubienie i kursywę dla słów i fraz kluczowych.</p><div class="why"><p>Uwaga: jeśli to cytat, można go wyodrębnić za pomocą znacznika blockquote.</p></div>`,
  QA_SUBSCRIPT: `<p><strong>Tekst:</strong> <i>%(TEXT)</i></p><p>Indeks dolny i górny sprawia, że tekst jest zbyt mały, by wiele osób mogło go łatwo przeczytać. Należy go używać tylko dla pojedynczych słów lub wyrażeń, np. w jednostkach miary (m<sup>2</sup>), wzorach chemicznych (H<sub>2</sub>O) i odwołaniach do przypisów.</p>`,
  QA_UNDERLINE: `<p>Podkreślony tekst w internecie oznacza linki, a nie wyróżnienie. Użytkownicy pomyślą, że mogą to kliknąć: <i><u>%(TEXT)</u></i></p><p>${why.fix}Do wyróżniania używaj <strong>pogrubienia</strong> lub <em>kursywy</em>, a do nadawania struktury — nagłówków.</p><div class="why"><p>Uwaga: czytniki ekranu nie ogłaszają formatowania wyłącznie wizualnego, takiego jak podkreślenia. Tylko nagłówki dodają tekst do struktury strony.</p></div>`,
  QA_UPPERCASE: `<p><strong>Tekst:</strong> <i>%(TEXT)</i></p><p>${why.fix}Wyróżniaj wielkimi literami tylko kilka słów. DUŻE BLOKI TEKSTU WIELKIMI LITERAMI SĄ TRUDNIEJSZE DO CZYTANIA, A WIELU CZYTELNIKÓW ODBIERA JE JAK KRZYK.</p><div class="why"><p>Uwaga: czytniki ekranu nie zapowiadają formatowania wyłącznie wizualnego, takiego jak tekst pisany wielkimi literami. Jeśli ten wyróżniony tekst wprowadza zmianę tematu lub szczególnie ważną treść, użyj stylu nagłówka.</p></div>`,
  SUS_ALT: `<p>Tekst alternatywny tego obrazu zawiera słowo „<i>%(alt)</i>”. Czytniki ekranu informują użytkownika, że opisują obraz, więc zwroty typu „obraz przedstawiający” lub „zdjęcie przedstawiające” zwykle są zbędne.</p><p><strong>Tekst alternatywny:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Krótko opisz, co ten obraz oznacza w danym kontekście.</p><div class="why"><p>Wskazówka: te zwroty warto zachować, jeśli sam format ma znaczenie:<br>„Zdjęcie kota, oprawione i wiszące na ścianie.”</p></div>`,
  TABINDEX_ATTR: `<p>Wartości tabindex większe niż 0 przenoszą elementy otrzymujące fokus poza ich wizualną kolejność, co utrudnia użytkownikom technologii wspomagających ich odnalezienie i obsługę.</p><p>${why.fix}Zmień kolejność elementów w HTML tak, aby kolejność fokusu i kolejność odczytu były spójne.</p><div class="why"><p>Wskazówka: wizualna kolejność słów na stronie i kolejność nawigacji tabulatorem są zwykle takie same.</p><p>Dodatni tabindex przenosi element na początek kolejności tabulacji, <strong>ale nie zmienia kolejności wizualnej ani odczytu</strong>.</p></div>`,
  TABLES_EMPTY_HEADING: `<p>${why.fix}Upewnij się, że każda komórka nagłówka zawiera tekst.</p><div class="why"><p>Wskazówka: czytniki ekranu używają nagłówków tabeli, aby pomóc użytkownikom orientować się podczas przeglądania tabeli. Odpowiedni nagłówek jest odczytywany ponownie, gdy kursor przechodzi do kolejnej kolumny lub wiersza.</p></div>`,
  TABLES_INVALID_HEADERS_REF: `<p>Ta tabela próbuje powiązać konkretną komórkę danych z konkretną komórką nagłówka, ale nie można znaleźć identyfikatora tej komórki nagłówka: <code>%(VALUE)</code>.</p><p>${why.fix}Upewnij się, że każdy atrybut <code>headers</code> odpowiada identyfikatorowi komórki nagłówka w tej samej tabeli.</p><div class="why">Wskazówka: <a href="https://www.w3.org/WAI/WCAG22/Techniques/html/H43">ręczne odwołania przez ID</a> wiążące komórki danych z komórkami nagłówka są skomplikowane i zawodne. W miarę możliwości dziel złożone dane na mniejsze tabele z prostymi wierszami i kolumnami nagłówka.</div>`,
  TABLES_MISSING_HEADINGS: `<p>${why.fix}Otwórz właściwości tabeli i określ, czy nagłówki tabeli znajdują się w pierwszym wierszu, w pierwszej kolumnie, czy w obu.</p><div class="why"> <p>Wskazówka: czytniki ekranu używają nagłówków tabeli, aby pomóc użytkownikom orientować się podczas przeglądania tabeli. Odpowiedni nagłówek jest odczytywany ponownie, gdy kursor przechodzi do kolejnej kolumny lub wiersza.</p><p>Jeśli ta tabela nie ma nagłówków, ponieważ służy tylko do wizualnego układu treści, usuń formatowanie tabeli i zamiast niego użyj czysto wizualnego formatowania kolumn.</p></div> `,
  TABLES_SEMANTIC_HEADING: `<p>${why.fix}Usuń to formatowanie nagłówka (h2, h3). Zamiast niego użyj wierszy i kolumn nagłówka. Jeśli potrzebujesz kilku wierszy nagłówka, podziel tę tabelę na kilka tabel.</p><div class="why"> <p>Wskazówka: nagłówki tabeli działają w jednym kierunku: w jednym wierszu lub jednej kolumnie. Nagłówki treści opisują cały następujący po nich tekst, nawet w niepowiązanych kolumnach:</p><table><tr><th>1</th><th>2</th><th>3</th><td rowspan="2"><strong>Nagłówek tabeli</strong> w komórce 2 opisuje komórkę B. <br><br> <strong>Nagłówek treści</strong> w komórce 2 opisuje komórki 3, A, B i C, a także ten tekst i stopkę tej podpowiedzi.</td></tr> <tr><td>A</td><td>B</td><td>C</td></tr></table> </div>`
};
